  reason: string;
}

/** One active staff member as a picker shows them (GET /staff/lookup): the facts on their badge and the registration their stamp prints, nothing else. */
export interface StaffLookupOut {
  /** The id a form's staff field takes (contrast_doctor_id, employee_id, ...) */
  employee_id: number;
  emp_number: string;
  full_name: string;
  designation: string;
  department_name: string | null;
  /** The council they are registered with (PMDC: a doctor or dentist; PNC: a nurse); null: none */
  license_type: "PMDC" | "PNC" | "Other" | null;
  /** As their stamp prints it, e.g. "PMDC 12345-P"; null: no number on file */
  registration: string | null;
  /** Their login, the id a form's user field takes (an action's owner, a signer, the person told); null: no login (decision 62) */
  user_id: number | null;
}

/** Admissions (default: all live ones; admissions desk queue) — GET /api/v1/admissions (who may call: holders of ipd.admission.view). */
export function listAdmissions(query?: { status?: string | null; ward_id?: number | null }): Promise<AdmissionOut[]> {
  return api<AdmissionOut[]>("GET", withQuery(`/admissions`, query), undefined);
}

/** Admission with bed, discharge stage and bill — GET /api/v1/admissions/{admission_id} (who may call: holders of ipd.admission.view). */
export function getAdmission(admission_id: number): Promise<AdmissionDetailOut> {
  return api<AdmissionDetailOut>("GET", `/admissions/${admission_id}`, undefined);
}

/** Vitals grid, nursing notes, schedule & next due time — GET /api/v1/admissions/{admission_id}/flowsheet (who may call: holders of ipd.flowsheet.view). */
export function flowsheet(admission_id: number): Promise<FlowsheetOut> {
  return api<FlowsheetOut>("GET", `/admissions/${admission_id}/flowsheet`, undefined);
}

/** Medication Administration Record (checklist) — GET /api/v1/admissions/{admission_id}/mar (who may call: holders of ipd.mar.view). */
export function mar(admission_id: number): Promise<MarEntryOut[]> {
  return api<MarEntryOut[]>("GET", `/admissions/${admission_id}/mar`, undefined);
}

/** Doctor: Discharge (Clinical Discharge stage) — POST /api/v1/admissions/{admission_id}/discharge (who may call: holders of ipd.discharge.initiate). */
export function discharge(admission_id: number, body: DischargeIn): Promise<AdmissionDetailOut> {
  return api<AdmissionDetailOut>("POST", `/admissions/${admission_id}/discharge`, body);
}

/** Which clearance stage the discharge is blocked on — GET /api/v1/admissions/{admission_id}/discharge-status (who may call: holders of ipd.admission.view or ipd.discharge.clear_pharmacy or ipd.discharge.clear_nursing or ipd.discharge.clear_billing or ipd.discharge.clear_cleaning). */
export function dischargeStatus(admission_id: number): Promise<DischargeStatusViewOut> {
  return api<DischargeStatusViewOut>("GET", `/admissions/${admission_id}/discharge-status`, undefined);
}

/** Record the reason for admission and the provisional diagnosis (Code Red) — POST /api/v1/admissions/{admission_id}/admission-details (who may call: holders of ipd.admission.request or ipd.discharge.initiate). */
export function admissionDetails(admission_id: number, body: AdmissionDetailsIn): Promise<AdmissionDetailOut> {
  return api<AdmissionDetailOut>("POST", `/admissions/${admission_id}/admission-details`, body);
}

/** List patient documents — GET /api/v1/patients/{patient_id}/documents (who may call: holders of patient.document.view). */
export function listDocumentsPatients(patient_id: number): Promise<PatientDocumentOut[]> {
  return api<PatientDocumentOut[]>("GET", `/patients/${patient_id}/documents`, undefined);
}

/** Download a patient document — GET /api/v1/patient-documents/{document_id}/download (who may call: holders of patient.document.view). */
export function downloadDocumentPatientDocuments(document_id: number): Promise<unknown> {
  return api<unknown>("GET", `/patient-documents/${document_id}/download`, undefined);
}

/** The live admissions and their treating doctors — GET /api/v1/ipd/treating-doctors (who may call: holders of ipd.admission.view or ipd.admission.reassign). */
export function listTreatingDoctors(query?: { doctor_id?: number | null; waiting?: boolean }): Promise<TreatingDoctorRowOut[]> {
  return api<TreatingDoctorRowOut[]>("GET", withQuery(`/ipd/treating-doctors`, query), undefined);
}

/** An inpatient's treating doctor and every change of it — GET /api/v1/admissions/{admission_id}/treating-doctor (who may call: holders of ipd.admission.view or ipd.admission.reassign). */
export function getTreatingDoctor(admission_id: number): Promise<TreatingDoctorOut> {
  return api<TreatingDoctorOut>("GET", `/admissions/${admission_id}/treating-doctor`, undefined);
}

/** Hand an inpatient over to another doctor — POST /api/v1/admissions/{admission_id}/treating-doctor (who may call: holders of ipd.admission.request or ipd.admission.reassign). */
export function changeTreatingDoctor(admission_id: number, body: TreatingDoctorIn): Promise<TreatingDoctorOut> {
  return api<TreatingDoctorOut>("POST", `/admissions/${admission_id}/treating-doctor`, body, { idempotent: true });
}

/** Find a staff member for a form (badge facts only) — GET /api/v1/staff/lookup (who may call: any logged-in user). */
export function lookupStaff(query: { q: string; department_id?: number | null; license_type?: "PMDC" | "PNC" | null; limit?: number }): Promise<StaffLookupOut[]> {
  return api<StaffLookupOut[]>("GET", withQuery(`/staff/lookup`, query), undefined);
}
